package com.tracksphere.interfaces.rest;
import com.tracksphere.application.location.LocationService; import com.tracksphere.application.location.dto.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/locations") @RequiredArgsConstructor public class LocationController { private final LocationService service; @PostMapping @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.CREATED) public LocationResponse record(@Valid @RequestBody LocationRequest request){return service.record(request);}@GetMapping("/live") public List<LocationResponse> live(){return service.live();}@GetMapping("/{vehicleId}/latest") public ResponseEntity<LocationResponse> latest(@PathVariable String vehicleId){return service.latest(vehicleId).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}@GetMapping("/{vehicleId}/history") public List<LocationResponse> history(@PathVariable String vehicleId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) Instant to){return service.history(vehicleId,from,to);} }
